# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor channel_cat_cuda(torch::Tensor a, torch::Tensor b);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("channel_cat_cuda", &channel_cat_cuda, "Channel concat CUDA");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void channel_cat_kernel(
    const scalar_t* __restrict__ a,
    const scalar_t* __restrict__ b,
    scalar_t* __restrict__ out,
    int64_t N, int64_t C1, int64_t C2, int64_t H, int64_t W
) {
    int64_t total = N * (C1 + C2) * H * W;
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = blockDim.x * gridDim.x;

    for (int64_t i = idx; i < total; i += stride) {
        int64_t w = i % W;
        int64_t h = (i / W) % H;
        int64_t c = (i / (W * H)) % (C1 + C2);
        int64_t n = i / (W * H * (C1 + C2));

        if (c < C1) {
            int64_t src_idx = ((n * C1 + c) * H + h) * W + w;
            out[i] = a[src_idx];
        } else {
            int64_t c2 = c - C1;
            int64_t src_idx = ((n * C2 + c2) * H + h) * W + w;
            out[i] = b[src_idx];
        }
    }
}

torch::Tensor channel_cat_cuda(torch::Tensor a, torch::Tensor b) {
    if (!a.is_cuda() || !b.is_cuda() ||
        a.dim() != 4 || b.dim() != 4 ||
        a.device() != b.device() ||
        a.scalar_type() != b.scalar_type() ||
        a.size(0) != b.size(0) ||
        a.size(2) != b.size(2) ||
        a.size(3) != b.size(3) ||
        !a.is_contiguous() || !b.is_contiguous()) {
        return torch::cat({a, b}, 1);
    }

    int64_t N = a.size(0);
    int64_t C1 = a.size(1);
    int64_t C2 = b.size(1);
    int64_t H = a.size(2);
    int64_t W = a.size(3);

    auto out = torch::empty({N, C1 + C2, H, W}, a.options());

    int64_t total = N * (C1 + C2) * H * W;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;
    blocks = std::min(blocks, 65535);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(a.scalar_type(), "channel_cat_kernel", [&] {
        channel_cat_kernel<scalar_t><<<blocks, threads>>>(
            a.data_ptr<scalar_t>(),
            b.data_ptr<scalar_t>(),
            out.data_ptr<scalar_t>(),
            N, C1, C2, H, W
        );
    });

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, in_channels, squeeze_channels, expand1x1_channels, expand3x3_channels):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                :param in_channels: Number of input channels
                :param squeeze_channels: Number of output channels for the squeeze layer
                :param expand1x1_channels: Number of output channels for the 1x1 expand layer
                :param expand3x3_channels: Number of output channels for the 3x3 expand layer
                """
        self.squeeze = nn.Conv2d(in_channels, squeeze_channels, kernel_size=1)
        self.squeeze_activation = nn.ReLU(inplace=True)
        self.expand1x1 = nn.Conv2d(squeeze_channels, expand1x1_channels, kernel_size=1)
        self.expand1x1_activation = nn.ReLU(inplace=True)
        self.expand3x3 = nn.Conv2d(squeeze_channels, expand3x3_channels, kernel_size=3, padding=1)
        self.expand3x3_activation = nn.ReLU(inplace=True)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                :param x: Input tensor, shape (batch_size, in_channels, height, width)
                :return: Output tensor, shape (batch_size, expand1x1_channels + expand3x3_channels, height, width)
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.squeeze_activation(self.squeeze(x))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        y1 = self.expand1x1_activation(self.expand1x1(x))
        y2 = self.expand3x3_activation(self.expand3x3(x))

        if (y1.is_cuda and y2.is_cuda and
            y1.is_contiguous() and y2.is_contiguous() and
            y1.dim() == 4 and y2.dim() == 4 and
            y1.device == y2.device and
            y1.dtype == y2.dtype and
            y1.size(0) == y2.size(0) and
            y1.size(2) == y2.size(2) and
            y1.size(3) == y2.size(3)):
            return _stark_get_extension().channel_cat_cuda(y1, y2)
        else:
            return torch.cat([y1, y2], 1)
        # <<<END_IMPROVE>>>

