__global__ void fire_expand1x1_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ w1,
    const scalar_t* __restrict__ b1,
    scalar_t* __restrict__ out,
    int N, int Cin, int C1, int H, int W
) {
