template <typename scalar_t>
__global__ void fire_expand_fused_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ w1,
    const scalar_t* __restrict__ b1,
    const scalar_t* __restrict__ w3,
    const scalar_t* __restrict__ b3,
    scalar_t* __restrict__ out,
    int64_t N, int64_t Cin, int64_t C1, int64_t C3, int64_t H, int64_t W
) {
    int64_t total = N * (C1 + C3) * H * W;
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = blockDim.x * gridDim.x;

    for (int64_t i = idx; i < total; i += stride) {
        int64_t w_pos = i % W;
        int64_t h_pos = (i / W) % H;
        int64_t c = (i / (W * H)) % (C1 + C3);
        int64_t n = i / (W * H * (C1 + C3));

        scalar_t val = 0;

        if (c < C1) {
            for (int64_t cin = 0; cin < Cin; ++cin) {
                val += __ldg(&input[((n * Cin + cin) * H + h_pos) * W + w_pos])
                     * __ldg(&w1[c * Cin + cin]);
            }
            if (b1) val += __ldg(&b1[c]);
        } else {
            int64_t c_out = c - C1;
            for (int64_t cin = 0; cin < Cin; ++cin) {
                for (int64_t kh = 0; kh < 3; ++kh) {
                    int64_t in_h = h_pos + kh - 1;
                    if (in_h < 0 || in_h >= H) continue;
                    for (int64_t kw = 0; kw < 3; ++kw) {
                        int64_t in_w = w_pos + kw - 1;
                        if (in_w < 0 || in_w >= W) continue;
                        val += __ldg(&input[((n * Cin + cin) * H + in_h) * W + in_w])
                             * __ldg(&w3[((c_out * Cin + cin) * 3 + kh) * 3 + kw]);
                    }
                }
            }
            if (b3) val += __ldg(&b3[c_out]);
        }
        out[i] = val > scalar_t(0) ? val : scalar_t(0);
    }
