// and computes a block of OC_BLOCK output channels, reusing loaded input values.
// Launch: grid.x = ceil(N*H*W / blockDim.x), grid.y = ceil((C1+C3)/OC_BLOCK)
// is_1x1: 1 for 1x1 branch, 0 for 3x3 branch
template <typename scalar_t, int MAX_CIN, int OC_BLOCK>
__global__ void fire_expand_ocblock_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ w1,
    const scalar_t* __restrict__ b1,
    const scalar_t* __restrict__ w3,
    const scalar_t* __restrict__ b3,
    scalar_t* __restrict__ out,
    int N, int Cin, int C1, int C3, int H, int W,
    int C_total  // C1 + C3
) {
    // blockIdx.y selects a channel block
    int c_base = blockIdx.y * OC_BLOCK;
    if (c_base >= C_total) return;

    // blockIdx.x / threadIdx.x selects a spatial position
    int nhw = blockIdx.x * blockDim.x + threadIdx.x;
    int NHW = N * H * W;
    if (nhw >= NHW) return;

    int w_pos = nhw % W;
    int h_pos = (nhw / W) % H;
    int n     = nhw / (H * W);

    // Load input values into registers
    // For 1x1: just the Cin values at (n, :, h, w)
    // For 3x3: the 3x3 neighborhood Cin values - load once per (cin, kh, kw)
    // We handle the unified case: first check if c_base is in 1x1 or 3x3 territory

    int c_end = c_base + OC_BLOCK;
    if (c_end > C_total) c_end = C_total;

