        } else {
            inp[cin] = scalar_t(0);
        }
    }

    for (int c = c_base; c < c_end; ++c) {
        scalar_t val = scalar_t(0);
        if (c < C1) {
            // 1x1 branch: reuse inp[]
            #pragma unroll
            for (int cin = 0; cin < MAX_CIN; ++cin) {
                if (cin < Cin) val += inp[cin] * __ldg(&w1[c * Cin + cin]);
            }
            if (b1) val += __ldg(&b1[c]);
        } else {
            // 3x3 branch
            int c_out = c - C1;
            #pragma unroll
            for (int cin = 0; cin < MAX_CIN; ++cin) {
                if (cin >= Cin) break;
                #pragma unroll
                for (int kh = 0; kh < 3; ++kh) {
                    int in_h = h_pos + kh - 1;
                    if (in_h < 0 || in_h >= H) continue;
                    #pragma unroll
                    for (int kw = 0; kw < 3; ++kw) {
                        int in_w = w_pos + kw - 1;
                        if (in_w < 0 || in_w >= W) continue;
                        val += __ldg(&input[((n * Cin + cin) * H + in_h) * W + in_w])
